{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 bucket lacks public access blocking",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no bucket-level public access block, leaving it vulnerable to future public ACL or bucket policy changes. This is particularly risky for a bucket containing logs."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Log bucket permits destructive deletion",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket and all versioned log objects without first emptying it, increasing the risk of irreversible audit-log loss."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
",
  "fix_summary": "Disabled forced deletion of the versioned log bucket and added a bucket-level public access block with all protections enabled. Existing encryption, versioning, ACL, and tags were preserved."
}
